-- KSOps migration 0001: shared extensions, organization, location, and IAM.
-- Target: PostgreSQL 16+. UUIDv7 values are generated by the application.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE SCHEMA IF NOT EXISTS org;
CREATE SCHEMA IF NOT EXISTS iam;
CREATE SCHEMA IF NOT EXISTS iam_private;

CREATE TABLE org.organization (
  id uuid PRIMARY KEY,
  code varchar(32) NOT NULL,
  legal_name varchar(180) NOT NULL,
  default_timezone varchar(64) NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  status varchar(20) NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'suspended')),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (code ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'),
  CHECK (updated_at >= created_at)
);

CREATE UNIQUE INDEX organization_code_unique_ci
  ON org.organization (lower(code));

CREATE TABLE org.branch (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  parent_branch_id uuid,
  code varchar(32) NOT NULL,
  name varchar(160) NOT NULL,
  kind varchar(20) NOT NULL
    CHECK (kind IN ('branch', 'station', 'office', 'depot', 'warehouse')),
  timezone varchar(64) NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  status varchar(20) NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'inactive')),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, code),
  FOREIGN KEY (organization_id, parent_branch_id)
    REFERENCES org.branch(organization_id, id),
  CHECK (code ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'),
  CHECK (parent_branch_id IS NULL OR parent_branch_id <> id),
  CHECK (updated_at >= created_at)
);

CREATE INDEX branch_org_status_idx
  ON org.branch (organization_id, status, kind);

-- Locations are operational, non-PII points. A private customer address must not
-- be copied into display_name or coordinates without an approved purpose.
CREATE TABLE org.location (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  branch_id uuid,
  public_code varchar(40) NOT NULL,
  kind varchar(24) NOT NULL
    CHECK (kind IN ('branch', 'station', 'office', 'depot', 'warehouse', 'service_zone')),
  display_name varchar(180) NOT NULL,
  latitude numeric(9,6),
  longitude numeric(9,6),
  status varchar(20) NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'inactive')),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, public_code),
  FOREIGN KEY (organization_id, branch_id)
    REFERENCES org.branch(organization_id, id),
  CHECK ((latitude IS NULL) = (longitude IS NULL)),
  CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  CHECK (updated_at >= created_at)
);

CREATE INDEX location_org_branch_status_idx
  ON org.location (organization_id, branch_id, status);

CREATE TABLE iam.principal (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  kind varchar(16) NOT NULL CHECK (kind IN ('human', 'service')),
  identity_provider varchar(120) NOT NULL,
  subject_hmac bytea NOT NULL CHECK (octet_length(subject_hmac) = 32),
  display_alias varchar(100) NOT NULL,
  status varchar(20) NOT NULL DEFAULT 'active'
    CHECK (status IN ('invited', 'active', 'suspended', 'revoked')),
  last_authenticated_at timestamptz,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, identity_provider, subject_hmac),
  CHECK (updated_at >= created_at)
);

CREATE INDEX principal_org_status_idx
  ON iam.principal (organization_id, status, kind);

-- Ciphertext and keyed blind indexes are generated outside PostgreSQL with KMS.
CREATE TABLE iam_private.principal_profile (
  principal_id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  full_name_ciphertext bytea,
  email_ciphertext bytea,
  email_lookup_hmac bytea CHECK (email_lookup_hmac IS NULL OR octet_length(email_lookup_hmac) = 32),
  phone_ciphertext bytea,
  phone_lookup_hmac bytea CHECK (phone_lookup_hmac IS NULL OR octet_length(phone_lookup_hmac) = 32),
  key_version smallint NOT NULL CHECK (key_version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, principal_id),
  FOREIGN KEY (organization_id, principal_id)
    REFERENCES iam.principal(organization_id, id),
  CHECK (updated_at >= created_at)
);

CREATE UNIQUE INDEX principal_profile_email_hmac_unique
  ON iam_private.principal_profile (organization_id, email_lookup_hmac)
  WHERE email_lookup_hmac IS NOT NULL;

CREATE TABLE iam.permission (
  key varchar(100) PRIMARY KEY,
  module varchar(40) NOT NULL,
  description varchar(240) NOT NULL,
  CHECK (key ~ '^[a-z][a-z0-9-]*:[a-z][a-z0-9-]*$')
);

CREATE TABLE iam.role (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  code varchar(50) NOT NULL,
  name varchar(120) NOT NULL,
  description varchar(300) NOT NULL DEFAULT '',
  status varchar(20) NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'inactive')),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, code),
  CHECK (updated_at >= created_at)
);

CREATE TABLE iam.role_permission (
  organization_id uuid NOT NULL,
  role_id uuid NOT NULL,
  permission_key varchar(100) NOT NULL REFERENCES iam.permission(key),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (organization_id, role_id, permission_key),
  FOREIGN KEY (organization_id, role_id)
    REFERENCES iam.role(organization_id, id)
);

CREATE TABLE iam.access_scope (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  kind varchar(20) NOT NULL CHECK (kind IN ('organization', 'branch')),
  branch_id uuid,
  parent_scope_id uuid,
  label varchar(120) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  FOREIGN KEY (organization_id, branch_id)
    REFERENCES org.branch(organization_id, id),
  FOREIGN KEY (organization_id, parent_scope_id)
    REFERENCES iam.access_scope(organization_id, id),
  CHECK (
    (kind = 'organization' AND branch_id IS NULL AND parent_scope_id IS NULL)
    OR (kind = 'branch' AND branch_id IS NOT NULL AND parent_scope_id IS NOT NULL)
  ),
  CHECK (parent_scope_id IS NULL OR parent_scope_id <> id)
);

CREATE UNIQUE INDEX access_scope_one_org_scope
  ON iam.access_scope (organization_id)
  WHERE kind = 'organization';

CREATE UNIQUE INDEX access_scope_one_per_branch
  ON iam.access_scope (organization_id, branch_id)
  WHERE kind = 'branch';

CREATE TABLE iam.principal_role_scope (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  principal_id uuid NOT NULL,
  role_id uuid NOT NULL,
  scope_id uuid NOT NULL,
  valid_during tstzrange NOT NULL,
  granted_by_principal_id uuid,
  grant_reason varchar(240) NOT NULL,
  revoked_at timestamptz,
  revoked_by_principal_id uuid,
  revoke_reason varchar(240),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  FOREIGN KEY (organization_id, principal_id)
    REFERENCES iam.principal(organization_id, id),
  FOREIGN KEY (organization_id, role_id)
    REFERENCES iam.role(organization_id, id),
  FOREIGN KEY (organization_id, scope_id)
    REFERENCES iam.access_scope(organization_id, id),
  FOREIGN KEY (organization_id, granted_by_principal_id)
    REFERENCES iam.principal(organization_id, id),
  FOREIGN KEY (organization_id, revoked_by_principal_id)
    REFERENCES iam.principal(organization_id, id),
  CHECK (NOT isempty(valid_during)),
  CHECK (lower(valid_during) IS NOT NULL),
  CHECK (lower_inc(valid_during) AND NOT upper_inc(valid_during)),
  CHECK (
    (revoked_at IS NULL AND revoked_by_principal_id IS NULL AND revoke_reason IS NULL)
    OR (revoked_at IS NOT NULL AND revoked_by_principal_id IS NOT NULL AND revoke_reason IS NOT NULL)
  ),
  CONSTRAINT principal_role_scope_no_overlap
    EXCLUDE USING gist (
      organization_id WITH =,
      principal_id WITH =,
      role_id WITH =,
      scope_id WITH =,
      valid_during WITH &&
    ) WHERE (revoked_at IS NULL)
);

CREATE INDEX principal_role_scope_lookup_idx
  ON iam.principal_role_scope (organization_id, principal_id, revoked_at);

-- Global permission vocabulary. It grants nothing until an audited organization
-- role is created and explicitly bound to a principal and scope.
INSERT INTO iam.permission (key, module, description) VALUES
  ('dashboard:read', 'dashboard', 'Read authorized operational dashboard projections'),
  ('cargo-order:read', 'cargo', 'Read cargo orders within data scope'),
  ('cargo-order:create', 'cargo', 'Create a cargo order'),
  ('cargo-order:transition', 'cargo', 'Apply an allowed cargo order transition'),
  ('cargo-order:resolve-exception', 'cargo', 'Resolve a cargo exception with reason'),
  ('cargo-order:read-pii', 'cargo', 'Reveal authorized cargo contact data'),
  ('dispatch:read', 'dispatch', 'Read dispatch tasks and assignments'),
  ('dispatch:assign', 'dispatch', 'Assign vehicle and driver resources'),
  ('dispatch:auto-assign', 'dispatch', 'Run an approved assignment suggestion'),
  ('dispatch:override', 'dispatch', 'Override a soft dispatch policy with reason'),
  ('vehicle:read', 'fleet', 'Read fleet operational data'),
  ('vehicle:update-status', 'fleet', 'Update an allowed vehicle status'),
  ('driver:read', 'workforce', 'Read driver operational data'),
  ('driver:read-restricted', 'workforce', 'Reveal authorized restricted driver data'),
  ('booking:read', 'passenger', 'Read bookings within data scope'),
  ('booking:create', 'passenger', 'Create a booking'),
  ('booking:cancel', 'passenger', 'Cancel a booking under policy'),
  ('contract:read', 'contract', 'Read rental contracts within data scope'),
  ('contract:create', 'contract', 'Create a rental request or contract draft'),
  ('contract:transition', 'contract', 'Apply an allowed contract transition'),
  ('contract:approve-quote', 'contract', 'Approve a quotation within authority'),
  ('customer:read', 'crm', 'Read masked customer data'),
  ('maintenance:read', 'maintenance', 'Read maintenance work'),
  ('maintenance:update-checklist', 'maintenance', 'Record maintenance checklist work'),
  ('maintenance:sign-off', 'maintenance', 'Sign off an eligible maintenance order'),
  ('maintenance:block-vehicle', 'maintenance', 'Block a vehicle for safety'),
  ('invoice:read', 'billing', 'Read invoices within accounting scope'),
  ('invoice:record-payment', 'billing', 'Record a reconciled payment reference'),
  ('report:read', 'reporting', 'Read authorized report projections'),
  ('report:export', 'reporting', 'Request an audited report export'),
  ('audit:read', 'audit', 'Read authorized redacted audit events'),
  ('audit:export', 'audit', 'Request an audited audit-event export')
ON CONFLICT (key) DO UPDATE
SET module = EXCLUDED.module,
    description = EXCLUDED.description;

COMMENT ON TABLE iam.principal IS
  'OIDC-backed principal metadata only; direct PII belongs in iam_private.';
COMMENT ON COLUMN iam.principal.subject_hmac IS
  'Keyed HMAC of issuer and subject; never store an access token or raw session claim.';
COMMENT ON TABLE iam.principal_role_scope IS
  'Time-bounded RBAC grant evaluated server-side together with data scope.';

COMMIT;
